package dev.tiertagger.client;
import net.fabricmc.fabric.api.client.keymapping.v1.KeyMappingHelper;import com.mojang.blaze3d.platform.InputConstants;import net.minecraft.client.KeyMapping;import net.minecraft.client.Minecraft;import net.minecraft.client.gui.screens.Screen;import net.minecraft.resources.Identifier;
public final class Platform {private static final KeyMapping.Category CATEGORY=KeyMapping.Category.register(Identifier.fromNamespaceAndPath("multi_tier_tagger","keys"));public static KeyMapping registerKey(){return KeyMappingHelper.registerKeyMapping(new KeyMapping("key.multi_tier_tagger.settings",InputConstants.Type.KEYSYM,InputConstants.KEY_I,CATEGORY));}public static KeyMapping registerNearestProfileKey(){return KeyMappingHelper.registerKeyMapping(new KeyMapping("key.multi_tier_tagger.nearest_profile",InputConstants.Type.KEYSYM,InputConstants.KEY_P,CATEGORY));}public static void overlay(Minecraft client,net.minecraft.network.chat.Component message){client.player.sendOverlayMessage(message);}public static Screen screen(Minecraft client){return client.gui.screen();}}
